/**
 * One page, ready to render as a pane.
 */
public struct PageView {
    /**
     * The dotted path of the container being listed; `""` is the document root.
     */
    public var focus: String
    /**
     * The trail from the root down to [`focus`](Self::focus), each step openable
     * by its `id`. **Empty at the root**, whose name is the frontend's to choose
     * — flower-core has none for it (the TUI calls it `‹document›`).
     */
    public var crumbs: [CrumbView]
    public var items: [PageItemView]
    /**
     * The selected item, or `None` for a pane that doesn't hold the cursor — a
     * preview, or the parent pane when what it marks is the page you opened.
     */
    public var selected: UInt32?
    /**
     * Whether this whole pane sits under a demoted key — the page you reached
     * by opening a demoted row. Lets a host keep the framing once you are
     * inside, rather than having a section stop applying one level in.
     */
    public var demoted: Bool

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * The dotted path of the container being listed; `""` is the document root.
         */focus: String, 
        /**
         * The trail from the root down to [`focus`](Self::focus), each step openable
         * by its `id`. **Empty at the root**, whose name is the frontend's to choose
         * — flower-core has none for it (the TUI calls it `‹document›`).
         */crumbs: [CrumbView], items: [PageItemView], 
        /**
         * The selected item, or `None` for a pane that doesn't hold the cursor — a
         * preview, or the parent pane when what it marks is the page you opened.
         */selected: UInt32?, 
        /**
         * Whether this whole pane sits under a demoted key — the page you reached
         * by opening a demoted row. Lets a host keep the framing once you are
         * inside, rather than having a section stop applying one level in.
         */demoted: Bool) {
        self.focus = focus
        self.crumbs = crumbs
        self.items = items
        self.selected = selected
        self.demoted = demoted
    }
}



extension PageView: Equatable, Hashable {
    public static func ==(lhs: PageView, rhs: PageView) -> Bool {
