/**
 * A failure constructing a document — the only fallible entry point. Every other
 * method operates on an already-parsed model and returns a [`DocView`] directly.
 */
public enum FlowerError {

    
    
    /**
     * The `format` string handed to [`FlowerDoc::new`] wasn't one flower knows.
     */
    case UnknownFormat(name: String
    )
    /**
     * fig failed to parse `source` as the requested format.
     */
    case Open(message: String
    )
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFlowerError: FfiConverterRustBuffer {
    typealias SwiftType = FlowerError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FlowerError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .UnknownFormat(
            name: try FfiConverterString.read(from: &buf)
            )
        case 2: return .Open(
            message: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FlowerError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .UnknownFormat(name):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(name, into: &buf)
            
        
        case let .Open(message):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(message, into: &buf)
            
        }
    }
}


